package com.rubidiumclient.module.visualimport android.graphics.Canvasimport android.graphics.Colorimport android.graphics.Paintimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.proxy.EntityTracker.TrackedEntityimport com.rubidiumclient.module.BaseModuleimport com.rubidiumclient.module.ModuleCategoryimport com.rubidiumclient.module.social.isFriendEntityimport com.rubidiumclient.utils.MathUtilimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.Jobimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.currentCoroutineContextimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.isActiveimport kotlinx.coroutines.launch/** * Tracks the nearest enemy and exposes it as a small immutable snapshot for * the draggable HUD box drawn by OverlayService, and also draws a tracer * line from screen center to that target on the full-screen ESP canvas. * * TargetHud used to be "EnemyESP", a full tracer/box/radar renderer for * every nearby entity. That's been narrowed to a single, focused job: decide * who the *current* target is, draw one clean tracer to them, and report * their name/health so OverlayService's draggable box can show it. The name * box (position, dragging, styling) still lives in OverlayService next to * the other HUD pieces (TotemCounterIcon, MenuFab, ...); this module only * owns the targeting logic and the tracer itself. */class TargetHud : BaseModule(    name = "TargetHud",    category = ModuleCategory.VISUAL,    description = "En yakın rakibi tracer ile gösterir, ismini taşınabilir bir kutuda listeler") {    companion object {        // FIX: Tracer'ın sürekli kaybolup yanlış yerde görünmesinin asıl        // sebebi buydu: hedef pozisyonu sadece 200ms'de bir (saniyede 5 kez)        // güncelleniyordu ama render() her frame'de (60fps) o BAYAT pozisyonu        // kullanıyordu. Hedef hareket ederken veya sen kamerayı çevirirken,        // tracer 200ms'lik "eski" bir noktaya çiziliyor, worldToScreen o eski        // nokta kameranın arkasında/dışında kaldığında null dönüp tracer'ı        // tamamen kayboluyordu. Artık render() her frame'de EntityTracker'dan        // hedefin CANLI pozisyonunu çekiyor; tick sadece "kim en yakın hedef"        // sorusunu periyodik cevaplıyor.        private const val TICK_INTERVAL_MS = 150L        const val CRITICAL_HEALTH = 5f        private const val PLAYER_WIDTH  = 0.6f        private const val PLAYER_HEIGHT = 1.8f    }    enum class TargetMode { Players, Hostiles, Both }    data class Target(        val runtimeId : Long,        val name      : String,        val x         : Float,        val y         : Float,        val z         : Float,        val isPlayer  : Boolean,        val health    : Float,        val maxHealth : Float,        val distance  : Float    ) {        val isCritical: Boolean get() = health in 0f..CRITICAL_HEALTH    }    private val targetMode    = enum("Target Mode", TargetMode.Players)    // FIX: eski max 128 idi ama default 32 çok düşüktü, kullanıcı asıl bunu    // demek istiyordu. Default 64'e, üst sınır 256'ya çıkarıldı.    private val scanRange     = float("Scan Range", 64f, 8f, 256f)    private val fov           = float("FOV", 70f, 30f, 130f)    private val ignoreFriends = bool("Ignore Friends", true)    private val showTracer    = bool("Show Tracer", true)    private val showBox       = bool("Show Box", true)    private val tracerWidth   = float("Tracer Width", 2.5f, 0.5f, 8f)    private val boxWidth      = float("Box Width", 2f, 0.5f, 6f)    private val hudDispatcher = Dispatchers.Default    private val hudScope      = CoroutineScope(SupervisorJob() + hudDispatcher)    private var tickJob: Job? = null    private val _target = MutableStateFlow<Target?>(null)    val target: StateFlow<Target?> = _target.asStateFlow()    private val tracerPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {        style = Paint.Style.STROKE        strokeCap = Paint.Cap.ROUND    }    override fun onEnable() {        super.onEnable()        tickJob = hudScope.launch {            while (currentCoroutineContext().isActive) {                if (isEnabled) {                    _target.value = runCatching { resolveNearestTarget() }.getOrNull()                }                delay(TICK_INTERVAL_MS)            }        }    }    override fun onDisable() {        super.onDisable()        tickJob?.cancel()        tickJob = null        _target.value = null    }    private fun resolveNearestTarget(): Target? {        val range = scanRange.value        val candidates: Collection<TrackedEntity> = when (targetMode.value) {            TargetMode.Players  -> EntityTracker.getPlayers(range)            TargetMode.Hostiles -> EntityTracker.getHostiles(range)            TargetMode.Both     -> EntityTracker.getPlayers(range) + EntityTracker.getHostiles(range)        }        val nearest = candidates            .asSequence()            .filter { it.runtimeId != EntityTracker.selfRuntimeId }            .filterNot { ignoreFriends.value && it.isFriendEntity }            .minByOrNull { EntityTracker.distanceTo(it) }            ?: return null        return Target(            runtimeId = nearest.runtimeId,            name      = nearest.name.ifBlank { nearest.identifier.removePrefix("minecraft:") },            x         = nearest.x, y = nearest.y, z = nearest.z,            isPlayer  = nearest.isPlayer,            health    = nearest.health,            maxHealth = nearest.maxHealth,            distance  = EntityTracker.distanceTo(nearest)        )    }    /**     * Draws a single tracer line from screen center to the current target,     * called every frame from ESPOverlayView alongside the other visual     * modules. Color follows the same "critical" logic as the HUD box: red     * once health drops below [CRITICAL_HEALTH], otherwise player/hostile     * tinted. No-ops silently if there's no target or it's off-screen.     */    private val boxPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {        style = Paint.Style.STROKE    }    fun render(canvas: Canvas, screenW: Int, screenH: Int) {        if (!isEnabled) return        val current = _target.value ?: return        // FIX: bayat (200ms'ye kadar eski) x/y/z yerine EntityTracker'dan        // hedefin O ANKİ canlı pozisyonunu çekiyoruz. Hedef sunucudan        // ayrılmış/görüş dışı kalmışsa null döner, o frame hiçbir şey        // çizilmez (bir sonraki tick temizler).        val live = EntityTracker.getById(current.runtimeId) ?: return        val color = when {            current.isCritical -> Color.rgb(255, 69, 58)            current.isPlayer   -> Color.rgb(0, 200, 255)            else                -> Color.rgb(255, 152, 0)        }        if (showTracer.value) {            val screenPos = MathUtil.worldToScreen(                live.x, live.y + 1.0f, live.z,                EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ,                EntityTracker.selfYaw, EntityTracker.selfPitch,                screenW, screenH,                fov.value            )            if (screenPos != null) {                tracerPaint.color = color                tracerPaint.strokeWidth = tracerWidth.value                canvas.drawLine(screenW / 2f, screenH / 2f, screenPos.first, screenPos.second, tracerPaint)            }        }        if (showBox.value) {            drawBox(canvas, screenW, screenH, live.x, live.y, live.z, color)        }    }    // "Dikdörtgen şeklinde 3 boyutlu" ESP kutusu: oyuncunun hitbox'ının 8    // köşesini ekrana projekte edip 12 kenarı çiziyoruz (alt kare + üst kare    // + 4 dikey bağlantı) — klasik wireframe ESP box.    private fun drawBox(canvas: Canvas, screenW: Int, screenH: Int, wx: Float, wy: Float, wz: Float, color: Int) {        val hw = PLAYER_WIDTH / 2f        val h  = PLAYER_HEIGHT        val corners = arrayOf(            floatArrayOf(-hw, 0f, -hw), floatArrayOf(hw, 0f, -hw),            floatArrayOf(hw, 0f,  hw),  floatArrayOf(-hw, 0f,  hw),            floatArrayOf(-hw, h, -hw),  floatArrayOf(hw, h, -hw),            floatArrayOf(hw, h,  hw),   floatArrayOf(-hw, h,  hw)        )        val screenPts = arrayOfNulls<Pair<Float, Float>>(8)        for (i in corners.indices) {            val c = corners[i]            screenPts[i] = MathUtil.worldToScreen(                wx + c[0], wy + c[1], wz + c[2],                EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ,                EntityTracker.selfYaw, EntityTracker.selfPitch,                screenW, screenH,                fov.value            )        }        if (screenPts.any { it == null }) return        boxPaint.color = color        boxPaint.strokeWidth = boxWidth.value        val edges = arrayOf(            0 to 1, 1 to 2, 2 to 3, 3 to 0,            4 to 5, 5 to 6, 6 to 7, 7 to 4,            0 to 4, 1 to 5, 2 to 6, 3 to 7        )        for ((a, b) in edges) {            val p1 = screenPts[a]!!; val p2 = screenPts[b]!!            canvas.drawLine(p1.first, p1.second, p2.first, p2.second, boxPaint)        }    }}